
#include "mml_h4_runtime.h"
#include <limits.h>
uint16_t mml_angle12_wrap(int32_t a){return (uint16_t)(a&0x0FFF);}int16_t mml_angle12_delta(uint16_t f,uint16_t t){int32_t d=((int32_t)t-f)&0xFFF;if(d>=0x800)d-=0x1000;return (int16_t)d;}
uint16_t mml_projection_heading12(uint16_t h,uint16_t o){return mml_angle12_wrap((int32_t)h-o);}
static int64_t edge2(int32_t ax,int32_t az,int32_t bx,int32_t bz,int32_t px,int32_t pz){return (int64_t)(px-ax)*(bz-az)-(int64_t)(pz-az)*(bx-ax);}
static bool inside(const MMLFloorTri*t,int32_t x,int32_t z){int64_t a=edge2(t->a.x,t->a.z,t->b.x,t->b.z,x,z),b=edge2(t->b.x,t->b.z,t->c.x,t->c.z,x,z),c=edge2(t->c.x,t->c.z,t->a.x,t->a.z,x,z);bool n=a<0||b<0||c<0,p=a>0||b>0||c>0;return !(n&&p);}
static bool py(const MMLFloorTri*t,int32_t x,int32_t z,int32_t*out){int64_t x1=t->a.x,z1=t->a.z,y1=t->a.y,x2=t->b.x,z2=t->b.z,y2=t->b.y,x3=t->c.x,z3=t->c.z,y3=t->c.y;int64_t den=(z2-z3)*(x1-x3)+(x3-x2)*(z1-z3);if(!den)return false;int64_t n1=(z2-z3)*(x-x3)+(x3-x2)*(z-z3),n2=(z3-z1)*(x-x3)+(x1-x3)*(z-z3),n3=den-n1-n2;*out=(int32_t)((n1*y1+n2*y2+n3*y3)/den);return true;}
bool mml_floor_query(const MMLFloorTri*t,size_t n,int32_t x,int32_t y,int32_t z,const MMLCollisionPolicy*p,MMLFloorHit*out){if(!t||!p||!out)return false;out->hit=false;int32_t best=INT32_MIN;uint32_t bi=0;for(size_t i=0;i<n;i++){if(t[i].ny_q12<p->min_floor_ny_q12||!inside(&t[i],x,z))continue;int32_t fy;if(!py(&t[i],x,z,&fy))continue;int32_t dy=fy-y;if(dy>p->max_step_up||(dy<0&&-dy>p->max_drop))continue;if(!out->hit||fy>best){out->hit=true;best=fy;bi=(uint32_t)i;}}if(!out->hit)return false;out->tri_index=bi;out->floor_y=best;out->nx_q12=t[bi].nx_q12;out->ny_q12=t[bi].ny_q12;out->nz_q12=t[bi].nz_q12;out->flags=t[bi].flags;return true;}
static const MMLTargetCandidate*find(const MMLTargetCandidate*c,size_t n,uint32_t id){for(size_t i=0;i<n;i++)if(c[i].id==id)return &c[i];return 0;}
static bool elig(const MMLTargetCandidate*c,uint16_t f,uint16_t a,uint32_t d){if(!c->alive||!c->targetable||c->distance_sq>d)return false;int16_t x=mml_angle12_delta(f,c->yaw_to_target12);if(x<0)x=(int16_t)-x;return (uint16_t)x<=a;}
bool mml_lockon_acquire(MMLLockOnState*s,uint16_t f,uint16_t ma,uint32_t md,const MMLTargetCandidate*c,size_t n){if(!s||!c)return false;const MMLTargetCandidate*b=0;uint16_t ba=0xFFFF;uint32_t bd=UINT32_MAX;for(size_t i=0;i<n;i++){if(!elig(&c[i],f,ma,md))continue;int16_t d=mml_angle12_delta(f,c[i].yaw_to_target12);uint16_t a=(uint16_t)(d<0?-d:d);if(!b||a<ba||(a==ba&&c[i].distance_sq<bd)||(a==ba&&c[i].distance_sq==bd&&c[i].id<b->id)){b=&c[i];ba=a;bd=c[i].distance_sq;}}if(!b){s->active=false;return false;}s->active=true;s->target_id=b->id;return true;}
bool mml_lockon_retain(MMLLockOnState*s,uint16_t f,uint16_t a,uint32_t d,const MMLTargetCandidate*c,size_t n){if(!s||!s->active)return false;const MMLTargetCandidate*t=find(c,n,s->target_id);if(!t||!elig(t,f,a,d)){s->active=false;return false;}return true;}
void mml_lockon_release(MMLLockOnState*s){if(s)s->active=false;}void mml_camera_set_owner(MMLCameraState*c,MMLCameraOwner o){if(c)c->owner=o;}void mml_camera_apply_lockon(MMLCameraState*c,const MMLLockOnState*l){if(!c||!l||c->owner==MML_CAM_SCRIPTED)return;c->owner=l->active?MML_CAM_LOCKON:MML_CAM_GAMEPLAY;c->target_valid=l->active;c->target_id=l->active?l->target_id:0;}
